    const ownerId=user.username||user.uuid||String(user.id||"cuenta");
    let stored=null;
    try{stored=await puter.kv.get(CLOUD_KEY)}catch{}
    if(typeof stored==="string"){try{stored=JSON.parse(stored)}catch{stored=null}}
    const current=stored&&typeof stored==="object"?stored:{state:null,version:0,updatedAt:0};
    if(method==="GET")return{ownerId,state:current.state||null,version:Number(current.version)||0,updatedAt:Number(current.updatedAt)||0};
