$("ccReportBody").addEventListener("input",e=>{const field=e.target.dataset.ccField;if(!field)return;const row=e.target.closest("[data-cc-row]"),id=row.dataset.ccRow.replace("update:","");let found=false;for(const sheet of state.updateSheets){const item=sheet.items.find(x=>x.id===id);if(item){item[field]=field==="price"?Number(e.target.value)||0:Number(e.target.value)||0;found=true;break}}if(found){save();renderCostReport();renderGeneral();renderPersonal();renderResponsibility()}});$("breakageToolsBody").addEventListener("click",e=>{const button=e.target.closest("[data-mark-broken]");if(button)openBreakage(button.dataset.markBroken)});$("breakageForm").addEventListener("submit",e=>{e.preventDefault();const item=breakageItems().find(entry=>entry.id===$("breakageItemId").value),quantity=Number($("breakageQuantity").value);if(!item)return;const alreadyBroken=state.movements.filter(move=>move.type==="Rotura"&&move.sourceItemId===item.id).reduce((sum,move)=>sum+(Number(move.quantity)||0),0),available=Math.max((Number(item.quantity)||0)-alreadyBroken,0);if(quantity<1||quantity>available){toast("La cantidad supera las unidades disponibles.");return}const observation=$("breakageObservation").value.trim();state.movements.push({id:crypto.randomUUID(),type:"Rotura",sourceItemId:item.id,responsible:item.responsible,name:item.name,description:observation,observation,costCenter:item.costCenter,department:item.department,quantity,price:Number(item.price)||0,date:$("breakageDate").value});save();$("breakageDialog").close();renderGeneral();renderBreakages();toast("Rotura registrada.")});$("newItemButton").addEventListener("click",()=>openItem());$("emptyNewButton").addEventListener("click",()=>openItem());$("settingsButton").addEventListener("click",openSettings);$("backupButton").addEventListener("click",()=>ui.backup.hidden=!ui.backup.hidden);
