Object.assign(window.inventoryAssistant||{},{
  search({texto="",centro_costo="",departamento="",responsable="",estado=""}={}){
    const normalize=value=>String(value||"").trim().toLocaleLowerCase("es");
    const query=normalize(texto),cc=normalize(centro_costo),dep=normalize(departamento),owner=normalize(responsable),status=normalize(estado);
    const matched=inventoryRecords().filter(item=>{
      const searchable=[item.name,item.code,item.costCenter,item.department,item.location,item.notes,item.responsible].map(normalize).join(" ");
      return (!query||searchable.includes(query))&&(!cc||normalize(item.costCenter)===cc)&&(!dep||normalize(item.department)===dep)&&(!owner||normalize(item.responsible)===owner)&&(!status||normalize(item.status)===status);
    });
    const records=matched.slice(0,80).map(item=>({
      id:item.id,name:item.name,code:item.code||"",quantity:Number(item.quantity)||0,price:Number(item.price)||0,
      status:item.status||"Bueno",cost_center:item.costCenter||"",department:item.department||"",
      responsible:item.responsible||"",description:item.isUpdate?item.notes||"":item.notes||"",
      location:item.location||"",type:item.isUpdate?"actualización":"inventario"
    }));
    return {
      count:matched.length,records,truncated:matched.length>records.length,
      total_units:matched.reduce((sum,item)=>sum+(Number(item.quantity)||0),0),
      total_value:matched.reduce((sum,item)=>sum+(Number(item.price)||0)*(Number(item.quantity)||0),0),
      by_status:matched.reduce((counts,item)=>{const label=item.status||"Bueno";counts[label]=(counts[label]||0)+1;return counts;},{})
    };
  },
  update({identificador,cambios={}}={}){
    const key=String(identificador||"").trim();
    const all=inventoryRecords();
    const matches=all.filter(item=>item.id===key||item.name.trim().toLocaleLowerCase("es")===key.toLocaleLowerCase("es"));
    if(matches.length!==1)return {error:matches.length?"Hay varios útiles con ese nombre. Indica el id del útil correcto.":"No encontré un útil con ese id o nombre.",options:matches.slice(0,20).map(({id,name,costCenter,department,responsible})=>({id,name,centro_costo:costCenter,departamento:department,responsable:responsible}))};
    const item=matches[0],isUpdate=item.isUpdate;
    const aliases={nombre:"name",codigo:"code",cantidad:"quantity",unidad:"unit",estado:"status",centro_costo:"costCenter",departamento:"department",ubicacion:"location",observaciones:"notes",descripcion:isUpdate?"description":"notes",precio:"price"};
    const source=isUpdate?state.updateSheets.flatMap(sheet=>sheet.items.map(entry=>({entry,sheet}))).find(row=>row.entry.id===item.id.slice("update:".length)):{entry:state.items.find(entry=>entry.id===item.id)};
    if(!source?.entry)return {error:"No pude encontrar el registro original para editarlo."};
    const allowed=isUpdate?new Set(["name","description","quantity","price"]):new Set(["name","code","quantity","unit","status","costCenter","department","location","notes"]);
    const submitted=Object.entries(cambios).filter(([,value])=>value!==undefined&&value!==null);
    if(!submitted.length)return {error:"Indica al menos un campo que quieras cambiar."};
    const pending=[],changed=[];
    for(const [field,value] of submitted){
      const property=aliases[field];
      if(!property||!allowed.has(property))return {error:isUpdate?"En registros de Actualización puedo cambiar nombre, descripción, cantidad y precio.":"Ese campo no se puede editar."};
      if(property==="quantity"||property==="price"){
        const number=Number(value);
        if(!Number.isFinite(number)||number<0||(property==="quantity"&&!Number.isInteger(number)))return {error:property==="quantity"?"La cantidad debe ser un entero igual o mayor que cero.":"El precio debe ser un número igual o mayor que cero."};
        pending.push([property,number]);
      }else if(property==="status"&&!["Bueno","Regular","Requiere reparación","Fuera de servicio"].includes(value)){
        return {error:"Estado no válido. Usa Bueno, Regular, Requiere reparación o Fuera de servicio."};
      }else{
        pending.push([property,String(value)]);
      }
      changed.push(field);
    }
    pending.forEach(([property,value])=>source.entry[property]=value);
    save();render();
    return {updated:true,id:item.id,name:source.entry.name,fields:changed,changes:source.entry};
  },
  filter({vista,texto="",estado="",departamento="",centro_costo="",responsable=""}={}){
    const views={inventario:"inventoryView",centro_costo:"ccView",general:"generalView",roturas:"breakagesView",responsabilidad:"responsibilityView",personal:"personalView",bajas:"disposalView"};
    const screen=views[vista];
    if(!screen)return {error:"Informe no reconocido."};
    const availableFilters={
      inventario:["texto","estado","departamento","responsable"],
      centro_costo:["centro_costo"],
      roturas:["responsable"],
      bajas:["responsable"],
      responsabilidad:["responsable"],
      personal:["responsable"],
      general:[]
    };
    const requested={texto,estado,departamento,centro_costo,responsable};
    const unsupported=Object.entries(requested).filter(([field,value])=>value&&!availableFilters[vista].includes(field)).map(([field])=>field);
    if(unsupported.length)return {error:"Ese informe no permite aplicar esos filtros desde la pantalla.",available_filters:availableFilters[vista]};
    const tab=document.querySelector(`.screen-tab[data-screen="${screen}"]`);
    if(tab)tab.click();
    else{
      document.querySelectorAll("main[id]").forEach(view=>view.hidden=view.id!==screen);
      $("newItemButton").hidden=false;
      renderInventory();
    }
    const normalized=value=>String(value||"").trim().toLocaleLowerCase("es");
    const selectMatch=(select,desired)=>{
      if(!desired){select.value="";select.dispatchEvent(new Event("change",{bubbles:true}));return {ok:true};}
      const option=[...select.options].find(entry=>normalized(entry.value)===normalized(desired)||normalized(entry.textContent)===normalized(desired));
      if(!option)return {ok:false,available:[...select.options].map(entry=>entry.textContent).filter(Boolean)};
      select.value=option.value;select.dispatchEvent(new Event("change",{bubbles:true}));return {ok:true,value:option.value};
    };
    const applied=[];
    if(vista==="inventario"){
      const box=$("searchInput");box.value=texto||responsable;$("departmentFilter").value="";$("statusFilter").value="";
      const departmentResult=selectMatch($("departmentFilter"),departamento);if(!departmentResult.ok)return {error:"No encontré el departamento.",available:departmentResult.available};
      const statusResult=selectMatch($("statusFilter"),estado);if(!statusResult.ok)return {error:"No encontré ese estado.",available:statusResult.available};
      box.dispatchEvent(new Event("input",{bubbles:true}));$("statusFilter").dispatchEvent(new Event("change",{bubbles:true}));
      if(texto||responsable)applied.push(responsable&&!texto?"responsable":"texto");if(departamento)applied.push("departamento");if(estado)applied.push("estado");
    }else if(vista==="centro_costo"){
      const result=selectMatch($("ccFilter"),centro_costo);if(!result.ok)return {error:"No encontré ese centro de costo.",available:result.available};if(centro_costo)applied.push("centro de costo");
    }else if(vista==="roturas"){
      const result=selectMatch($("breakageResponsibleFilter"),responsable);if(!result.ok)return {error:"No encontré ese responsable en Roturas.",available:result.available};if(responsable)applied.push("responsable");
    }else if(vista==="bajas"){
      const result=selectMatch($("disposalResponsible"),responsable);if(!result.ok)return {error:"No encontré ese responsable en Solicitud de Baja.",available:result.available};if(responsable)applied.push("responsable");
    }else if(vista==="responsabilidad"||vista==="personal"){
      $(vista==="personal"?"personalResponsible":"responsibilitySheetSelect").value="";
      $(vista==="personal"?"personalResponsible":"responsibilitySheetSelect").dispatchEvent(new Event("change",{bubbles:true}));
      if(responsable){
        const sheets=state.updateSheets.filter(sheet=>sheet.responsible?.trim()&&normalized(sheet.responsible)===normalized(responsable));
        if(!sheets.length)return {error:"No encontré ese responsable en el informe."};
        if(sheets.length>1)return {error:"Hay más de una asignación para esa persona. Indica centro de costo o departamento.",options:sheets.map(sheet=>({centro_costo:sheet.costCenter,departamento:sheet.department,responsable:sheet.responsible}))};
        const value=JSON.stringify([sheets[0].costCenter||"",sheets[0].department||"",sheets[0].responsible||""]);
        $(vista==="personal"?"personalResponsible":"responsibilitySheetSelect").value=value;
        $(vista==="personal"?"personalResponsible":"responsibilitySheetSelect").dispatchEvent(new Event("change",{bubbles:true}));
        applied.push("responsable");
      }
    }
    return {shown:screen,filters:applied,message:applied.length?"Informe filtrado.":"Informe abierto."};
  }
});
